GPUParticleAdvection.expression:
new GPUParticleAdvection({
        id: 'advect',
        velocities: view('velocity', velocityBuffer, 'float32x2', FIELD_CELLS),
        fieldWidth: FIELD.width,
        fieldHeight: FIELD.height,
        parameters: advectionParameters.importToGraph(advectionGraph),
        uint32Parameters: words,
        state: {
          positions,
          ages: view('ages', particleAges, 'uint32', count),
          generations: view('generations', particleGenerations, 'uint32', count)
        }
      })

getGPUParticleAdvectionParameterValues(
        {
          fieldExtent: FIELD.extent,
          timeStep: 1,
          speedScale: scale,
          // Particles that leave the data stay parked outside the field instead of respawning.
          spawnBounds: [PARKING[0], PARKING[1], PARKING[0], PARKING[1]]
        },
        [FIELD.width, FIELD.height]
      )

getGPUParticleAdvectionUint32ParameterValues({
          seed: 1,
          frame: day,
          maximumAge: 0,
          reset: false
        })

getGPUParticleAdvectionUint32ParameterValues({
          seed: options.seed,
          frame: particleFrame,
          maximumAge: options.maximumAge,
          reset: resetParticles
        })

new GPUParticleAdvection({
        id: 'particles',
        velocities: view('velocity', velocityBuffer, 'float32x2', FIELD_CELLS),
        fieldWidth: FIELD_WIDTH,
        fieldHeight: FIELD_HEIGHT,
        parameters: particleParameters.importToGraph(graph),
        uint32Parameters: particleWords.importToGraph(graph),
        state: {
          positions: view('positions', positions, 'float32x2', count),
          ages: view('ages', ages, 'uint32', count),
          generations: view('generations', generations, 'uint32', count)
        },
        output: {
          speeds: view('speeds', speedsOut, 'float32', count),
          trails: {
            positions: view('trails', trails, 'float32x2', count * trailLength),
            length: trailLength
          }
        }
      })

getGPUParticleAdvectionParameterValues(
            {
              fieldExtent: FIELD_EXTENT,
              // Seconds of wind per frame: about 2 px for a 40 m/s wind at zoom 5, kept constant on screen.
              timeStep: 120 * zoomFactor,
              speedScale: state.speedScale,
              dropRate: state.dropRate,
              minimumSpeed: state.minimumSpeed * DEGREES_PER_METER * state.speedScale,
              spawnBounds
            },
            [FIELD_WIDTH, FIELD_HEIGHT]
          )

getGPUParticleAdvectionUint32ParameterValues({
            seed: state.seed,
            frame: particleFrame,
            maximumAge: state.maximumAge,
            reset: resetParticles
          })

GPUCostDistancePath.expression:
new GPUCostDistancePath({
        id: 'path',
        grid: grid.rasterGrid,
        backLinks: importGraphBuffer(
          pathGraph,
          'back-links',
          buffers.backLinks,
          'uint32',
          cellCount
        ),
        target: targetView,
        output: {
          path: {
            ids: pathIds,
            status: {
              count: pathCount,
              overflow: importGraphBuffer(
                pathGraph,
                'path-overflow',
                buffers.pathOverflow,
                'uint32',
                1
              ),
              requiredCount: importGraphBuffer(
                pathGraph,
                'path-total-output',
                buffers.pathTotal,
                'uint32',
                1
              )
            }
          },
          // 1 when the cost phase hit its iteration limit: back-links are unresolved, path is empty.
          status: {
            iterationLimitReached: importGraphBuffer(
              pathGraph,
              'path-iteration-limit',
              buffers.pathIterationLimit,
              'uint32',
              1
            )
          }
        }
      })

