        {maximumDistance: ctx.options.coastSearchKm * 1000 * maximumScaleFactor},
        coastGrid
      )

getGPUDistanceFieldParameterValues(
        {
          maximumDistance:
            options.distanceCap >= NO_DISTANCE_CAP_KILOMETERS
